CREATE TRIGGER `trg_GW001_results_playoff_div_bi` BEFORE INSERT ON `GW001_IMC Results` FOR EACH ROW PRECEDES `trg_GW001_results_playoff_bi` SET NEW.sm_division=CASE WHEN NEW.game_world_id='GW001' AND (REGEXP_LIKE(TRIM(COALESCE(NEW.sm_action,'')), '^play[[:space:]-]*offs?$', 'i') OR REGEXP_LIKE(TRIM(COALESCE(NEW.competition_stage,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(NEW.competition_group_name,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(NEW.competition_round,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i')) THEN (SELECT CASE WHEN h.division_value IN ('2','3','4') AND h.division_value=a.division_value AND h.club_division=h.division_value AND a.club_division=a.division_value THEN h.division_value ELSE NULL END FROM gw_world_clubs h JOIN gw_world_clubs a ON a.game_world_id=h.game_world_id JOIN gw_source_captures hc ON hc.capture_id=h.capture_id AND hc.game_world_id=h.game_world_id AND hc.capture_status='complete' JOIN gw_source_captures ac ON ac.capture_id=a.capture_id AND ac.game_world_id=a.game_world_id AND ac.capture_status='complete' WHERE h.game_world_id='GW001' AND h.world_club_id=NEW.home_sm_club_id AND a.world_club_id=NEW.away_sm_club_id AND hc.generated_at < DATE_ADD(NEW.match_date,INTERVAL 1 DAY) AND ac.generated_at < DATE_ADD(NEW.match_date,INTERVAL 1 DAY)) ELSE NEW.sm_division END;

