CREATE TRIGGER `trg_GW001_mr_playoff_key_bi` BEFORE INSERT ON `GW001_IMC Match Report` FOR EACH ROW FOLLOWS `trg_GW001_mr_playoff_div_bi` SET NEW.competition_key=CASE WHEN NEW.game_world_id='GW001' AND ((REGEXP_LIKE(TRIM(COALESCE(NEW.sm_action,'')), '^play[[:space:]-]*offs?$', 'i') OR REGEXP_LIKE(TRIM(COALESCE(NEW.competition_stage,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(NEW.competition_round,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i')) OR EXISTS (SELECT 1 FROM `GW001_IMC Results` r WHERE r.game_world_id=NEW.game_world_id AND r.sm_fixture_id=NEW.sm_fixture_id AND r.home_sm_club_id=NEW.home_sm_club_id AND r.away_sm_club_id=NEW.away_sm_club_id AND r.match_date=NEW.match_date AND (REGEXP_LIKE(TRIM(COALESCE(r.sm_action,'')), '^play[[:space:]-]*offs?$', 'i') OR REGEXP_LIKE(TRIM(COALESCE(r.competition_stage,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(r.competition_group_name,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(r.competition_round,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i')))) THEN CONCAT_WS('|',NEW.game_world_id,CASE WHEN UPPER(TRIM(COALESCE(NEW.sm_country,''))) IN ('','CUS') THEN NULL ELSE UPPER(TRIM(NEW.sm_country)) END,'DOMESTIC','playoff',NULLIF(TRIM(NEW.sm_division),'')) ELSE NEW.competition_key END;

